        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) ^ (b < 0):
            q = -q
        return q

    def parse_expr():
        nonlocal i
        left = parse_term()
        while True:
            skip_spaces()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                right = parse_term()
                if op == "+":
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def parse_term():
        nonlocal i
        left = parse_factor()
        while True:
            skip_spaces()
            if i < n and s[i] in "*/":
                op = s[i]
                i += 1
                right = parse_factor()
                if op == "*":
                    left *= right
                else:
                    left = truncate_divide(left, right)
            else:
                break
        return left

    def parse_factor():
        nonlocal i
        skip_spaces()
        if i < n and s[i] == "-":
            i += 1
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        nonlocal i
        skip_spaces()
        if i < n and s[i].isdigit():
            return parse_number()
        if i < n and s[i] == "(":
            i += 1
            value = parse_expr()
            skip_spaces()
            if i < n and s[i] == ")":
                i += 1
            return value
        raise ValueError(f"Unexpected character at position {i}: {s[i]!r}")

    result = parse_expr()
    skip_spaces()
    return result
