def evaluate(s):
    n = len(s)
    pos = 0

    def skip_spaces():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1

    def parse_expression():
        nonlocal pos
        value = parse_term()

        while pos < n:
            skip_spaces()
            if pos < n and s[pos] == '+':
                pos += 1
                rhs = parse_term()
                value += rhs
            elif pos < n and s[pos] == '-':
                pos += 1
                rhs = parse_term()
                value -= rhs
            else:
                break

        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()

        while pos < n:
            skip_spaces()
            if pos < n and s[pos] == '*':
                pos += 1
                rhs = parse_factor()
                value *= rhs
            elif pos < n and s[pos] == '/':
                pos += 1
                rhs = parse_factor()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                sign = -1 if (value < 0) != (rhs < 0) else 1
                value = sign * (abs(value) // abs(rhs))
            else:
                break

        return value

    def parse_factor():
        nonlocal pos
        skip_spaces()

        if pos >= n:
            raise ValueError("unexpected end of expression")

        ch = s[pos]

        if ch == '-':
            pos += 1
            return -parse_factor()

        if ch == '+':
            pos += 1
            return parse_factor()

        if ch == '(':
            pos += 1
            value = parse_expression()
            skip_spaces()
            if pos >= n or s[pos] != ')':
                raise ValueError("missing closing parenthesis")
            pos += 1
            return value

        if ch.isdigit():
            start = pos
            while pos < n and s[pos].isdigit():
                pos += 1
            return int(s[start:pos])

        raise ValueError(f"unexpected character: {ch}")

    value = parse_expression()
    skip_spaces()
    if pos != n:
        raise ValueError("unexpected trailing characters")
    return value
